-- GENERATED by `wfi generate` from data/quest/quest-0093.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [93035] = { "Devastare i ravager", "Mantieni la tua reputazione con il Gelkis Clan e uccidi $N1 Undead Ravager, poi torna da Nerlokh all'ingresso meridionale della Valley of Bones.", "Non serve guardare lontano per vedere i non morti che barcollano davanti a noi, ma hai notato qualcosa di insolito in loro?\n\nCamminano su due gambe, non su quattro! Questi scheletri non sono nemmeno dei nostri caduti. I Magram devono profanare i corpi di chi è morto molto prima che Desolace fosse il nostro dominio. Non riesco a immaginare come abbiano giustificato il voltare le spalle a madre Theradras e il dedicarsi a profanare cadaveri che riposavano qui da secoli.\n\nDai pace ai non morti, {name}.", nil, nil, 0x153e1e0b, 0x5480b72b, 0x3fc928fd, nil, nil, "...mm" },
  [93066] = { nil, "Mantieni la tua reputazione con i Magram e uccidi i quilboar al Bristleback Retreat. Poi fai rapporto a Hagiak al Magram Front, dall'altra parte della Valley of Bones, a Desolace.", "Dall'altra parte della valle abbiamo stabilito un piccolo avamposto per prepararci a marciare nella foresta vicina. Prima che tu vada direttamente lì, voglio che ti occupi di una recente incursione dei Bristleback lungo la strada. Sembra che siano arrivati più o meno nello stesso momento in cui siamo arrivati noi, ma sono riusciti a impadronirsi di un manufatto del tempio vicino che ci tiene a distanza.\n\nIl compito è semplice. Cerca le spine e i maiali. Uccidine un bel po', senza distinzione. Poi fai rapporto a Hagiak all'accampamento di cui ti ho parlato.", nil, nil, nil, 0x895f28cd, 0x20e4bcb9, nil, nil, "m..mm" },
  [93125] = { "Tornare a casa", "Mantieni la tua reputazione con i Gelkis e scorta Rokren fuori dall'Outcast Hideaway. Poi informa Nerlokh, vicino alla Valley of Bones, di quanto è successo.", "Tu! Ti ho visto fuori combattere i reietti. Non so da dove vieni, ma ho bisogno del tuo aiuto.\n\nSono stato attirato qui dai miei fratelli Gelkis con la promessa di sicurezza. Sapevo che la guerra a Desolace stava sfuggendo al nostro controllo, ma non avrei mai immaginato che la mia stessa gente si sarebbe rivolta alla negromanzia in un contorto tentativo di passare al clan Magram. Quando mi sono opposto, hanno minacciato di uccidermi se avessi mai messo zoccolo fuori da questa tenda!\n\nTi prego, aiutami.", nil, nil, 0xf193b151, 0x86ad2352, 0x15267230, nil, nil, "...mm" },
  [93128] = { nil, "Mantieni la tua reputazione con i Gelkis e uccidi il Khan Jhen al Magram Village. Una volta riuscita l'impresa, fai rapporto a Uthek the Wise, al Gelkis Village di Desolace.", "Per quanto vorrei che fossero Uthek o il Khan Shaka a dare l'ordine, temo che la nostra finestra di opportunità sia breve. Troppo breve per consultare quelli del Gelkis Village.\n\nCredo che, con la situazione che si sta sviluppando qui nella Valley of Bones, i Magram abbiano lasciato il Khan Jehn con difese minime. Se mai c'è stato un momento per attaccare il Khan di un altro clan, è adesso.\n\nMa {name}, con un Khan non si scherza, men che meno con Jehn. Se sei abbastanza <coraggioso/coraggiosa> da fare la tua mossa, devi essere <rapido/rapida>, ma non sottovalutarlo.", nil, nil, nil, 0xe9180567, 0xe9fc8e6f, nil, nil, "m..mm" },
  [93196] = { nil, "Mantieni la tua reputazione con i Magram e compi un rituale di negromanzia per resuscitare il Khan Jehn. Il luogo del rituale si trova in una tenda presso il lago centrale del Magram Village.", "Il capo del nostro clan, il Khan Jehn, è stato ucciso da una banda di stranieri molto simili a te. Agivano per conto del clan Gelkis.\n\nPuoi smettere di fingerti <sorpreso/sorpresa>. Un assalto al Magram Village mentre la nostra attenzione era altrove è una strategia di guerra prevedibile, specialmente per i Gelkis.\n\nSai perché non mostro né rabbia né rimorso, <straniero/straniera>?\n\n<Orgrul ti porge un'arma familiare, infusa di un potere ancora più grande dell'ultima volta che l'hai impugnata.>\n\nEcco perché.", nil, nil, nil, 0x571f4b9c, 0xc11d031e, nil, nil, "m..mm" },
  [93224] = { nil, "Ottieni $N1 Carved Centaur Totems uccidendo centauri di qualsiasi clan in tutta Desolace, poi portali al Captain Pentigast, a Nijel's Point.", "Probabilmente non ti sorprenderà che entrambi i clan di centauri siano restii ad accettare aiuto da chiunque non faccia parte del loro clan. Questo vale soprattutto per gente come te e me: sai, i non centauri.\n\nUna cosa che abbiamo tutti in comune è la consapevolezza che il denaro è potere, e abbiamo scoperto che i centauri del posto barattano con legno intagliato. Se mi porti qualche esempio dei loro intagli, posso ordinare con urgenza incisioni simili. Forse potremo comprarci un vantaggio.", nil, nil, nil, 0xa608090a, 0x7f0dbe84, nil, nil, "m..mm" },
  [93225] = { nil, "Ottieni $N1 Carved Centaur Totems uccidendo centauri di qualsiasi clan in tutta Desolace, poi portali a Gurda Wildmane, al Ghost Walker Post.", "Ho notato che centauri di clan diversi a volte si riuniscono lontano dagli insediamenti e commerciano. L'ho osservato per numerose notti e apparentemente con ogni clan; soprattutto ho visto la moneta che usano: totem intagliati.\n\nCredo che possiamo volgere le sorti a nostro favore con i Gelkis o con i Magram se consegniamo loro direttamente un pesante fagotto di totem. Ho già cominciato a intagliarne qualcuno, ma dubito che si lasceranno ingannare facilmente senza qualche esemplare autentico.", nil, nil, nil, 0x19fc2936, 0xb3fe9d43, nil, nil, "m..mm" },
  [93226] = { "Comprare l'amicizia: Magram", "Porta il Totem Tote al Magram Quartermaster, al Magram Village di Desolace, per aumentare notevolmente la tua reputazione con quel clan. Devi avere almeno la reputazione Neutral con i Magram Clan Centaur.", "Schierarsi con i Magram sarebbe la mia scelta. Non c'è dubbio che oggi siano il clan dominante, indipendentemente dalle loro difficoltà passate. Ho sentito rapporti secondo cui sono brutalmente ostili verso i Gelkis.\n\nProvo simpatia per entrambi i clan in guerra, e specialmente per i Gelkis, ma questa è la loro guerra, non la nostra. Dovremmo schierarci con la fazione che rappresenta il rischio minore per la nostra causa. Credo che siano i Magram.\n\nPorta questo al loro furiere, al Magram Village a sud-est.", nil, nil, 0xf5fd14ba, 0x66df78e4, 0xe1f3c90b, nil, nil, "...mm" },
  [93227] = { "Comprare l'amicizia: Gelkis", "Porta il Totem Tote al Gelkis Quartermaster, al Gelkis Village di Desolace, per aumentare notevolmente la tua reputazione con quel clan. Devi avere almeno la reputazione Neutral con i Gelkis Clan Centaur.", "A prima vista scommetterei che i Gelkis siano in difficoltà. Sono molti meno dei Magram, e i nostri esploratori raramente me ne parlano.\n\nAd ogni modo sono uno dei clan dominanti di Desolace e sopravvivono ancora oggi. Devono fare qualcosa di giusto.\n\nSe vuoi fare pace con i Gelkis, porta questa borsa di totem al Gelkis Village, lontano a sud-ovest. Per quanto primitivi, probabilmente hanno una specie di tesoriere.", nil, nil, 0x57c3db29, 0x68c32afb, 0xc65c6911, nil, nil, "...mm" },
  [93464] = { "Il mago in visita", "Trova il mago di Desolace che conosce il potere del draenethyst.", "Lascia che ti confessi una cosa, {name}. Anche se il draenethyst è sacro per noi e ci mantiene sani di mente, nessuno qui lo comprende davvero.\n\nRicordo un mago che venne una volta all'Harborage, da Desolace. Un umano di nome Azore. Temeva il potere del draenethyst; diceva che non doveva finire nelle mani sbagliate.\n\nAllora lo cacciammo per proteggere ciò che era nostro. Ultimamente, però, mi ritrovo a chiedermi cosa sapesse esattamente.\n\nTi chiedo di trovare questo mago, {race}. Le sue conoscenze potrebbero esserci immensamente preziose.", nil, nil, 0x8dd4d8e6, 0x5dd0e284, 0x339bbfeb, nil, nil, "...mm" },
  [93963] = { "Esplorare l'Alliance", "Parla con Randal Emerson nello Stormwind Keep per ricevere ulteriori istruzioni. Usa le istruzioni ricevute per trovare e parlare con King Magni Bronzebeard, l'High Tinker Mekkatorque e Tyrande Whisperwind.", "Stormwind, Ironforge e Darnassus hanno popoli e culture uniche. Come ospite dell'Alliance qui su Azeroth, dovresti prenderti un po' di tempo per visitare a turno ciascuna delle nostre capitali.\n\nParla con Randal Emerson nell'anticamera meridionale per avere le indicazioni con cui cominciare.", nil, "Ah, sei <tornato/tornata>.\n\nSpero che le tue avventure ti abbiano dato un'idea della vastità e delle meraviglie del nostro mondo. So che deve sembrarti travolgente, ma se vuoi aiutare la tua gente devi essere <pronto/pronta> a qualunque cosa ti capiti mentre sei su Azeroth.\n\nMentre attendi che il tuo ordine si stabilisca a Dalaran, ti suggerisco di rivolgere l'attenzione alle terre intorno a Stormwind. Westfall in particolare ha sempre bisogno di altri avventurieri forti che le diano una mano, se sei <disposto/disposta>.", 0xb5c2bf15, 0x80cbe7b7, 0x7db457d1, nil, 0xd5e8b7c2, "...m." },
})
